export const toScoredSearchResultFromSemantic = ({
  uid,
  title,
  type,
  nodeTypeLabel,
  score,
  resultsByUid,
}: {
  uid: string;
  title: string;
  type?: string;
  nodeTypeLabel?: string;
  score: number;
  resultsByUid: Map<string, SearchResult>;
}): ScoredSearchResult => {
  const indexedResult = resultsByUid.get(uid);
  if (indexedResult) {
    return { result: indexedResult, score, source: "semantic" };
  }

  return {
    result: {
      uid,
      title,
      type: type || "",
      nodeTypeLabel: nodeTypeLabel || "",
      excerpt: "",
      createdAt: "",
      lastModified: "",
      authorName: "Unknown",
    },
    score,
    source: "semantic",
  };
};

export type SortField = "relevance" | "alphabetical" | "dateCreated" | "author";
export type SortDirection = "asc" | "desc";

export type SortConfig = {
  field: SortField;
  direction: SortDirection;
};

export const DEFAULT_SORT_CONFIG: SortConfig = {
  field: "relevance",
  direction: "desc",
};

export const SORT_FIELD_LABELS: Record<SortField, string> = {
  relevance: "Relevance",
  alphabetical: "Alphabetical",
