193	  useEffect(() => {
194	    const timeout = setTimeout(
195	      () => setDebouncedSearchTerm(searchTerm.trim()),
196	      DEBOUNCE_MS,
197	    );
198	    return () => clearTimeout(timeout);
199	  }, [searchTerm]);
200	
201	  useEffect(() => {
202	    let cancelled = false;
203	    setIsIndexLoading(true);
204	    setIndexError(false);
205	    setSearchIndex(null);
206	
207	    void buildSearchIndex(discourseNodes)
208	      .then(({ miniSearch, results: indexedResults }) => {
209	        if (cancelled) return;
210	        setSearchIndex({ miniSearch, allResults: indexedResults });
211	        setIsIndexLoading(false);
