282	        {indexError ? (
283	          <NonIdealState
284	            icon="error"
285	            title="Search unavailable"
286	            description="Reload the extension and try again."
287	          />
288	        ) : (
289	          <>
290	            <span className="ml-2 text-xs">
291	              {isIndexLoading && !results.length
292	                ? "Loading…"
293	                : debouncedSearchTerm
294	                  ? `${resultLabel} for “${debouncedSearchTerm}”`
295	                  : "Type to search"}
296	            </span>
297	            {isIndexLoading && !results.length ? (
298	              <div className="flex justify-center py-4">
299	                <Spinner size={SpinnerSize.SMALL} />
300	              </div>
301	            ) : (
302	              <>
303	                {debouncedSearchTerm && results.length > 0 && (
304	                  <AdvancedSearchSidebarResultsList
305	                    keywords={keywords}
306	                    results={results}
307	                  />
308	                )}
309	                {debouncedSearchTerm &&
310	                  !results.length &&
311	                  !isIndexLoading &&
312	                  !isSearching && (
313	                    <p className="px-2 py-3 text-sm text-gray-500">
314	                      No matches. Try another keyword.
315	                    </p>
