1	import React from "react";
2	import renderWithUnmount from "roamjs-components/util/renderWithUnmount";
3	import { AdvancedSearchSidebarPanel } from "./AdvancedSearchSidebarPanel";
4	import type { DockedSearchState } from "./utils";
5	
6	const STORAGE_KEY = "dg-advanced-search-sidebar-windows";
7	const DG_SEARCH_ROOT_CLASS = "dg-node-search-sidebar-root";
8	const SIDEBAR_OPEN_WIDTH_PX = 40;
9	const MAX_WINDOW_WAIT_FRAMES = 30;
10	
11	type RoamSidebarWindow = {
12	  type: string;
13	  "window-id": string;
14	  "search-query-str"?: string;
15	};
16	
17	type PersistedDockedSearchState = DockedSearchState & {
18	  dgSearchId: string;
19	  windowId: string;
20	  updatedAt: number;
21	};
22	
23	type PersistedDockedSearchRegistry = Record<string, PersistedDockedSearchState>;
24	
25	const activeUnmounts = new Map<string, () => void>();
26	const mountingDgSearchIds = new Set<string>();
27	
28	const isRightSidebarOpen = (): boolean => {
29	  const sidebar = document.getElementById("right-sidebar");
30	  return (
31	    !!sidebar && sidebar.getBoundingClientRect().width > SIDEBAR_OPEN_WIDTH_PX
32	  );
33	};
34	
35	const getRoamSidebarWindows = async (): Promise<RoamSidebarWindow[]> => {
36	  try {
37	    const windows = await Promise.resolve(
38	      window.roamAlphaAPI.ui.rightSidebar.getWindows(),
39	    );
40	    return windows ?? [];
41	  } catch {
42	    return [];
43	  }
44	};
45	
46	const readRegistry = (): PersistedDockedSearchRegistry => {
47	  try {
48	    const raw = localStorage.getItem(STORAGE_KEY);
49	    if (!raw) return {};
50	
51	    const parsed = JSON.parse(raw) as PersistedDockedSearchRegistry;
52	    if (!parsed || typeof parsed !== "object") return {};
53	
54	    return parsed;
55	  } catch {
56	    return {};
57	  }
58	};
59	
60	const writeRegistry = (registry: PersistedDockedSearchRegistry): void => {
61	  localStorage.setItem(STORAGE_KEY, JSON.stringify(registry));
62	};
63	
64	const upsertRegistryEntry = ({
65	  dgSearchId,
66	  windowId,
67	  state,
68	}: {
69	  dgSearchId: string;
70	  windowId: string;
71	  state: DockedSearchState;
72	}): void => {
73	  const registry = readRegistry();
74	
75	  for (const [id, entry] of Object.entries(registry)) {
76	    if (entry.windowId === windowId && id !== dgSearchId) {
77	      delete registry[id];
78	    }
79	  }
80	
81	  registry[dgSearchId] = {
82	    ...state,
83	    dgSearchId,
84	    windowId,
85	    updatedAt: Date.now(),
86	  };
87	  writeRegistry(registry);
88	};
89	
90	const pruneRegistry = (liveWindowIds: Set<string>): void => {
91	  const registry = readRegistry();
92	  let changed = false;
93	
94	  for (const dgSearchId of Object.keys(registry)) {
95	    if (liveWindowIds.has(registry[dgSearchId].windowId)) continue;
96	    delete registry[dgSearchId];
97	    changed = true;
98	  }
99	
100	  if (changed) writeRegistry(registry);
101	};
102	
103	const listDgSearchWindows = (): PersistedDockedSearchState[] =>
104	  Object.values(readRegistry());
105	
106	const getSearchContainer = (sidebarWindow: HTMLElement): HTMLElement | null =>
107	  sidebarWindow.querySelector<HTMLElement>(".rm-sidebar-search");
108	
109	const findNewWindowId = (
110	  before: RoamSidebarWindow[],
111	  after: RoamSidebarWindow[],
112	): string | null => {
113	  const beforeIds = new Set(before.map((window) => window["window-id"]));
114	  const newWindows = after.filter(
115	    (window) => !beforeIds.has(window["window-id"]),
116	  );
117	  const searchQueryWindow = newWindows.find(
118	    (window) => window.type === "search-query",
119	  );
120	  return (
121	    searchQueryWindow?.["window-id"] ?? newWindows[0]?.["window-id"] ?? null
122	  );
123	};
124	
125	const waitForSidebarWindowElement = async (
126	  windowId: string,
127	): Promise<HTMLElement> => {
128	  for (let attempt = 0; attempt < MAX_WINDOW_WAIT_FRAMES; attempt += 1) {
129	    const sidebarWindow = document.querySelector<HTMLElement>(
130	      `[data-sidebar-window-id="${windowId}"]`,
131	    );
132	    if (sidebarWindow) return sidebarWindow;
133	
134	    await new Promise<void>((resolve) => {
135	      requestAnimationFrame(() => resolve());
136	    });
137	  }
138	  throw new Error("DG search sidebar window did not appear");
139	};
140	
141	const mountPanelInSearchWindow = ({
142	  dgSearchId,
143	  dockedState,
144	  sidebarWindow,
145	  windowId,
146	}: {
147	  dgSearchId: string;
148	  dockedState: DockedSearchState;
149	  sidebarWindow: HTMLElement;
150	  windowId: string;
151	}): void => {
152	  if (mountingDgSearchIds.has(dgSearchId)) return;
153	
154	  mountingDgSearchIds.add(dgSearchId);
155	  try {
156	    activeUnmounts.get(dgSearchId)?.();
157	    activeUnmounts.delete(dgSearchId);
158	
159	    const searchContainer = getSearchContainer(sidebarWindow);
160	    if (!searchContainer) {
161	      throw new Error("DG search sidebar window is missing .rm-sidebar-search");
162	    }
163	
164	    searchContainer.innerHTML = "";
165	
166	    const root = document.createElement("div");
167	    root.className = `${DG_SEARCH_ROOT_CLASS} box-border w-full min-w-0`;
168	    root.dataset.dgSearchId = dgSearchId;
169	    root.dataset.dgWindowId = windowId;
170	    root.onmousedown = (event) => event.stopPropagation();
171	    searchContainer.appendChild(root);
172	
173	    const stateWithIds: DockedSearchState = {
174	      ...dockedState,
175	      dgSearchId,
176	      windowId,
177	    };
178	
179	    upsertRegistryEntry({ dgSearchId, windowId, state: stateWithIds });
180	
181	    const unmount = renderWithUnmount(
182	      <AdvancedSearchSidebarPanel
183	        dgSearchId={dgSearchId}
184	        dockedState={stateWithIds}
185	        onPersistState={(nextState) => {
186	          upsertRegistryEntry({ dgSearchId, windowId, state: nextState });
187	        }}
188	        windowId={windowId}
189	      />,
190	      root,
191	    );
192	
193	    activeUnmounts.set(dgSearchId, unmount);
194	
195	    const titleEl = sidebarWindow.querySelector<HTMLElement>(
196	      ".window-headers span[style*='font-weight']",
197	    );
198	    if (titleEl) titleEl.textContent = "DG node search";
199	  } finally {
200	    mountingDgSearchIds.delete(dgSearchId);
201	  }
202	};
203	
204	const restorePersistedDockedSearchSidebarWindows = (): void => {
205	  for (const savedState of listDgSearchWindows()) {
206	    const sidebarWindow = document.querySelector<HTMLElement>(
207	      `[data-sidebar-window-id="${savedState.windowId}"]`,
208	    );
209	    if (!sidebarWindow || activeUnmounts.has(savedState.dgSearchId)) {
210	      continue;
211	    }
212	
213	    mountPanelInSearchWindow({
214	      dgSearchId: savedState.dgSearchId,
215	      dockedState: savedState,
216	      sidebarWindow,
217	      windowId: savedState.windowId,
218	    });
219	  }
220	};
221	
222	const syncDockedSearchWindows = async (): Promise<void> => {
223	  const roamWindows = await getRoamSidebarWindows();
224	  const liveWindowIds = new Set(
225	    roamWindows.map((window) => window["window-id"]),
226	  );
227	  pruneRegistry(liveWindowIds);
228	  restorePersistedDockedSearchSidebarWindows();
229	};
