231	export const mountAdvancedSearchInSidebar = async (
232	  dockedState: DockedSearchState,
233	): Promise<void> => {
234	  const dgSearchId = window.roamAlphaAPI.util.generateUID();
235	  const roamWindowsBefore = await getRoamSidebarWindows();
236	
237	  await window.roamAlphaAPI.ui.rightSidebar.addWindow({
238	    window: {
239	      type: "search-query",
240	      // @ts-expect-error - search-query-str replaces block-uid for search-query windows
241	      // eslint-disable-next-line @typescript-eslint/naming-convention
242	      "search-query-str": dockedState.query,
243	    },
244	  });
245	
246	  const roamWindowsAfter = await getRoamSidebarWindows();
247	  const windowId = findNewWindowId(roamWindowsBefore, roamWindowsAfter);
248	  if (!windowId) {
