import path from "node:path";

const TOKEN = "zorbquokka";
const FIXTURE_PAGE = "ENG-2366 candidate fixture";

const dialog = (page) => page.locator(".bp3-dialog").filter({
  has: page.locator('[aria-label="Display options"]'),
});

const closeOverlays = async (page) => {
  for (let i = 0; i < 4; i += 1) {
    if ((await page.locator(".bp3-overlay-open").count()) === 0) return;
    await page.keyboard.press("Escape");
    await page.waitForTimeout(200);
  }
};

const openSearch = async (page) => {
  await closeOverlays(page);
  await page.keyboard.press("Meta+p");
  await page.keyboard.type("DG: Open Node Search");
  await page.waitForTimeout(400);
  await page.keyboard.press("Enter");
  await dialog(page).waitFor({ timeout: 10000 });
};

const waitForSearch = async (page) => {
  await page.waitForTimeout(600);
  await page.waitForFunction(
    () => {
      const d = document.querySelector(".bp3-dialog");
      if (!d || d.querySelector(".bp3-spinner")) return false;
      return (
        !!d.querySelector('[role="listbox"]') ||
        /No matches/.test(d.textContent || "")
      );
    },
    null,
    { timeout: 20000 },
  );
};

const search = async (page, term) => {
  await dialog(page).locator("input").first().fill(term);
  await waitForSearch(page);
};

const readRows = (page) =>
  page.evaluate(() =>
    Array.from(
      document.querySelectorAll('.bp3-dialog [role="listbox"] [role="option"]'),
    ).map((row) => {
      const tag = row.querySelector(".bp3-tag");
      return {
        text: row.querySelector("span.min-w-0")?.textContent || "",
        badge: tag?.textContent || "",
        candidateLabel: tag?.getAttribute("aria-label") || null,
        badgeBackground: tag ? getComputedStyle(tag).backgroundColor : null,
      };
    }),
  );

const setShowCandidates = async (page, on) => {
  await dialog(page).locator('[aria-label="Display options"]').click();
  const toggle = page.locator(".bp3-popover .bp3-switch input");
  await toggle.waitFor({ state: "attached" });
  if ((await toggle.isChecked()) !== on) {
    await page.locator(".bp3-popover .bp3-switch").click();
  }
  const checked = await toggle.isChecked();
  return checked;
};

const selectRow = async (page, text) => {
  await dialog(page)
    .locator('[role="option"]')
    .filter({ hasText: text })
    .first()
    .click();
};

const footer = (page, label) =>
  dialog(page).locator("button").filter({ hasText: new RegExp(`^.*${label}$`) });

export default {
  async ready({ page }) {
    await closeOverlays(page);
    return true;
  },

  async run({ page, outDir }) {
    const proof = {};
    const shot = async (name) => {
      const file = path.join(outDir, `eng2366-${name}.png`);
      await page.screenshot({ path: file });
      return file;
    };

    const fixture = await page.evaluate(
      async ({ TOKEN, FIXTURE_PAGE }) => {
        const api = window.roamAlphaAPI;
        const format = api.q(`[:find ?v . :where
          [?p :node/title "discourse-graph/nodes/Result"]
          [?b :block/page ?p] [?b :block/string "Format"]
          [?b :block/children ?c] [?c :block/string ?v]]`);
        const nodeTitle = format.replace("{content}", `${TOKEN} node result`);
        const pageUid = api.util.generateUID();
        await api.data.page.create({
          page: { title: FIXTURE_PAGE, uid: pageUid },
        });
        const nodeUid = api.util.generateUID();
        await api.data.page.create({ page: { title: nodeTitle, uid: nodeUid } });
        const blocks = {
          result: `${TOKEN} soil result #res-candidate`,
          claim: `${TOKEN} claim idea #claim`,
          shared: `${TOKEN} shared #res-candidate #claim`,
          plain: `${TOKEN} plain block`,
        };
        const uids = {};
        let order = 0;
        for (const [key, string] of Object.entries(blocks)) {
          uids[key] = api.util.generateUID();
          await api.data.block.create({
            location: { "parent-uid": pageUid, order: order++ },
            block: { string, uid: uids[key] },
          });
        }
        return { pageUid, nodeUid, nodeTitle, uids };
      },
      { TOKEN, FIXTURE_PAGE },
    );
    proof.fixture = fixture;
    globalThis.__eng2366Fixture = fixture;
    await page.waitForTimeout(1500);

    // Toggle off: today's results.
    await openSearch(page);
    await search(page, TOKEN);
    proof.toggleOffRows = await readRows(page);
    proof.toggleOffShot = await shot("1-toggle-off");

    // Toggle on: candidates appear with outlined badges and stripped text.
    proof.switchCheckedAfterOn = await setShowCandidates(page, true);
    proof.menuShot = await shot("2-display-options-menu");
    await page.keyboard.press("Escape");
    await page.waitForTimeout(300);
    proof.dialogOpenAfterEscapeOnMenu = (await dialog(page).count()) === 1;
    proof.menuClosedAfterEscape =
      (await page.locator(".bp3-popover .bp3-switch").count()) === 0;
    await waitForSearch(page);
    proof.toggleOnRows = await readRows(page);
    proof.toggleOnShot = await shot("3-toggle-on");

    // Matches on block text, not just the token.
    await search(page, `${TOKEN} soil`);
    proof.blockTextMatchRows = await readRows(page);

    // Type filter applies to candidates.
    await search(page, TOKEN);
    await dialog(page).locator('[aria-label^="Filter by type"]').click();
    await page.locator('input[placeholder="Filter types…"]').fill("Claim");
    await page
      .locator(".bp3-popover .bp3-checkbox")
      .filter({ hasText: /^Claim$/ })
      .first()
      .click();
    await page.keyboard.press("Escape");
    await waitForSearch(page);
    proof.claimFilterRows = await readRows(page);
    proof.filterShot = await shot("4-claim-filter");
    await dialog(page).locator('[aria-label^="Filter by type"]').click();
    await page
      .locator(".bp3-popover .bp3-checkbox")
      .filter({ hasText: "Select all" })
      .click();
    await page.keyboard.press("Escape");
    await waitForSearch(page);

    // Sorting applies to candidates.
    await dialog(page).locator('[aria-label^="Sort by"]').click();
    await page.locator(".bp3-menu-item").filter({ hasText: "Alphabetical" }).click();
    await page.locator(".bp3-popover button", { hasText: "Asc" }).click();
    await page.keyboard.press("Escape");
    await waitForSearch(page);
    proof.alphabeticalAscRows = (await readRows(page)).map((r) => r.text);

    // Insert is disabled for candidates (shown only with an insert target).
    await selectRow(page, "soil result");
    proof.insertButtonForCandidate = await footer(page, "insert")
      .first()
      .evaluate((el) => (el ? el.disabled : "absent"))
      .catch(() => "absent");

    // Open goes to the tagged block.
    await footer(page, "open").first().click();
    await page.waitForTimeout(1200);
    proof.openedUrl = page.url();
    proof.openedBlockUid = fixture.uids.result;
    proof.openWentToBlock = page.url().includes(fixture.uids.result);

    // Toggle resets when the dialog reopens; sidebar opens the block.
    await openSearch(page);
    proof.switchCheckedOnReopen = await setShowCandidates(page, false);
    await page.keyboard.press("Escape");
    await search(page, TOKEN);
    proof.reopenRows = await readRows(page);
    await setShowCandidates(page, true);
    await page.keyboard.press("Escape");
    await waitForSearch(page);
    await selectRow(page, "claim idea");
    await footer(page, "sidebar").first().click();
    await page.waitForTimeout(1200);
    proof.sidebarWindows = await page.evaluate(() =>
      window.roamAlphaAPI.ui.rightSidebar
        .getWindows()
        .map((w) => ({ type: w.type, uid: w["block-uid"] })),
    );
    proof.sidebarHasClaimBlock = proof.sidebarWindows.some(
      (w) => w.uid === fixture.uids.claim,
    );

    // Docked panel keeps the toggle.
    await openSearch(page);
    await setShowCandidates(page, true);
    await page.keyboard.press("Escape");
    await search(page, TOKEN);
    await footer(page, "dock results").first().click();
    await page.waitForTimeout(2500);
    proof.dock = await page.evaluate(() => {
      const panel = document.querySelector(".dg-node-search-sidebar");
      return panel
        ? {
            showingCandidates: /Showing candidate nodes/.test(
              panel.textContent || "",
            ),
            rows: Array.from(
              panel.querySelectorAll(".rm-search-query__page-row-title"),
            ).map((el) => el.textContent),
          }
        : null;
    });
    proof.dockShot = await shot("5-docked-panel");
    return proof;
  },

  async cleanup({ page }) {
    await closeOverlays(page);
    await page.evaluate(async (FIXTURE_PAGE) => {
      const api = window.roamAlphaAPI;
      const fixture = window.__eng2366FixtureUids;
      for (const w of api.ui.rightSidebar.getWindows()) {
        await api.ui.rightSidebar.removeWindow({
          window: { type: w.type, "window-id": w["window-id"] },
        });
      }
      const pageUid = api.q(
        `[:find ?u . :where [?p :node/title "${FIXTURE_PAGE}"] [?p :block/uid ?u]]`,
      );
      if (pageUid) await api.data.page.delete({ page: { uid: pageUid } });
      const nodeUid = api.q(`[:find ?u . :where [?p :node/title ?t]
        [(clojure.string/includes? ?t "zorbquokka node result")] [?p :block/uid ?u]]`);
      if (nodeUid) await api.data.page.delete({ page: { uid: nodeUid } });
      return fixture;
    }, FIXTURE_PAGE);
    return { removed: true };
  },
};

